package com.jobportal.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.core.userdetails.UserDetailsService; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserDetailsService uds; private final TokenBlacklist blacklist; public JwtFilter(JwtService jwt, UserDetailsService uds, TokenBlacklist blacklist){this.jwt=jwt;this.uds=uds;this.blacklist=blacklist;}
 protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,java.io.IOException{String h=req.getHeader("Authorization"); String t=null; if(h!=null&&h.startsWith("Bearer ")) t=h.substring(7); else if(req.getCookies()!=null) for(var c:req.getCookies()) if("HF_ACCESS".equals(c.getName())) {t=c.getValue();break;} if(t!=null){try{if(!blacklist.contains(t)&&"access".equals(jwt.type(t))){String email=jwt.email(t);if(SecurityContextHolder.getContext().getAuthentication()==null){var d=uds.loadUserByUsername(email);var a=new UsernamePasswordAuthenticationToken(d,null,d.getAuthorities());SecurityContextHolder.getContext().setAuthentication(a);}}}catch(Exception ignored){}}chain.doFilter(req,res);}}
